using TrEInvoice.Core; using TrEInvoice.Validation;
namespace TrEInvoice.Validation.Tests;
public class ValidationTests { [Fact] public void Required_fields_are_checked(){var r=new InvoiceValidator().Validate(InvoiceDocument.Empty()); Assert.Contains(r.Issues,x=>x.Code=="INV001"); Assert.Contains(r.Issues,x=>x.Code=="INV002"); Assert.Contains(r.Issues,x=>x.Code=="INV003"); Assert.Contains(r.Issues,x=>x.Code=="INV004"); Assert.Contains(r.Issues,x=>x.Code=="INV005");} [Fact] public void Negative_amount_is_invalid(){var i=InvoiceDocument.Empty() with { Id="x", Uuid=Guid.NewGuid(), IssueDate=DateOnly.FromDateTime(DateTime.Today), Supplier=new("s"), Customer=new("c"), Lines=[new("1","x",1,new(-1,"TRY"),new(-1,"TRY"),[],new(0,"TRY"),new(0,"TRY"))]}; Assert.False(new InvoiceValidator().Validate(i).IsValid);} [Fact] public void Invalid_currency_and_inconsistent_totals_are_invalid(){var i=InvoiceDocument.Empty() with {Id="x",Uuid=Guid.NewGuid(),IssueDate=DateOnly.FromDateTime(DateTime.Today),Currency="T",Supplier=new("s"),Customer=new("c"),Lines=[new("1","x",1,new(10,"T"),new(9,"T"),[],new(0,"T"),new(0,"T"))]}; var r=new InvoiceValidator().Validate(i); Assert.Contains(r.Issues,x=>x.Code=="INV006"); Assert.Contains(r.Issues,x=>x.Code=="INV009"); Assert.All(r.Issues,x=>Assert.False(string.IsNullOrWhiteSpace(x.Path)));} [Fact] public void Validation_and_reconciliation_are_repeatable(){var invoice=InvoiceDocument.Empty() with {Totals=new(new(0,"TRY"),new(0,"TRY"),new(0,"TRY"),new(1,"TRY"),new(0,"TRY"),new(0,"TRY"))}; var validator=new InvoiceValidator(); Assert.Equal(validator.Validate(invoice).Issues,validator.Validate(invoice).Issues); var result=validator.Reconcile(invoice); Assert.False(result.IsReconciled); Assert.NotEmpty(result.Issues);} [Fact] public void Tax_and_payable_mismatches_have_field_paths(){var invoice=InvoiceDocument.Empty() with {Id="SYN",Uuid=Guid.NewGuid(),IssueDate=new DateOnly(2026,1,1),Supplier=new("Seller"),Customer=new("Buyer"),Lines=[new("1","Synthetic item",1,new(10,"TRY"),new(10,"TRY"),[],new(0,"TRY"),new(0,"TRY"))],Taxes=[new(new("X","Generic tax","Custom"),20,new(1,"TRY"))],Totals=new(new(10,"TRY"),new(10,"TRY"),new(12,"TRY"),new(9,"TRY"),new(0,"TRY"),new(0,"TRY"))}; var issues=new InvoiceValidator().Validate(invoice).Issues; Assert.Contains(issues,x=>x.Code=="INV012"&&x.Path=="Totals.TaxInclusiveAmount"); Assert.Contains(issues,x=>x.Code=="INV013"&&x.Path=="Totals.PayableAmount");} }
